// EnterpriseOrder defines model for EnterpriseOrder.
type EnterpriseOrder struct {
	AcceptedAt   *time.Time `json:"acceptedAt,omitempty"`
	BillingRef   *string    `json:"billingRef,omitempty"`
	CancelReason *string    `json:"cancelReason,omitempty"`
	CancelledAt  *time.Time `json:"cancelledAt,omitempty"`
	CompanyName  string     `json:"companyName"`
	CompletedAt  *time.Time `json:"completedAt,omitempty"`
	CostCenter   *string    `json:"costCenter,omitempty"`
	CreatedAt    time.Time  `json:"createdAt"`

	// DeadlineAt Acceptance deadline; auto-cancel after
	DeadlineAt     *time.Time `json:"deadlineAt,omitempty"`
	DeliveryEtaMin *int       `json:"deliveryEtaMin,omitempty"`

	// DispatchStrategy Strategy-pattern dispatch: instant uses nearest; cross-city uses multi_leg; warehouse-fulfilled uses warehouse
	DispatchStrategy *EnterpriseOrderDispatchStrategy `json:"dispatchStrategy,omitempty"`
	FreeDelivery     *bool                            `json:"freeDelivery,omitempty"`

	// FulfillmentSource Regional-warehouse model: nearest warehouse ships when inventory is pre-positioned
	FulfillmentSource *EnterpriseOrderFulfillmentSource `json:"fulfillmentSource,omitempty"`

	// FulfillmentType intercity = hub-to-hub with line-haul; relay = sequential rider handoffs
	FulfillmentType *EnterpriseOrderFulfillmentType `json:"fulfillmentType,omitempty"`
	Id              openapi_types.UUID              `json:"id"`

	// ItemsChecked Item-wise verification completed on this order
	ItemsChecked *bool              `json:"itemsChecked,omitempty"`
	MerchantId   openapi_types.UUID `json:"merchantId"`

	// No Human-readable order number
	No *string `json:"no,omitempty"`

	// PreOrderReminderSent Persists on the order row after the ≤15 min reminder
	PreOrderReminderSent *bool `json:"preOrderReminderSent,omitempty"`

	// Priority Priority tagging; VIP/express orders take precedence in dispatch and list sorting
	Priority *EnterpriseOrderPriority `json:"priority,omitempty"`

	// PromoCode Rider promo order — bonus credited on completion
	PromoCode        *string             `json:"promoCode,omitempty"`
	ReadyAt          *time.Time          `json:"readyAt,omitempty"`
	RejectReason     *string             `json:"rejectReason,omitempty"`
	RejectReasonCode *string             `json:"rejectReasonCode,omitempty"`
	RiderId          *openapi_types.UUID `json:"riderId,omitempty"`

	// RouteSegments Multi-leg journey (first mile, line-haul, hub transfer, last mile)
	RouteSegments *[]RouteSegment `json:"routeSegments,omitempty"`

	// RushCooldownMinutes Second rush within cooldown keeps deadline unchanged
	RushCooldownMinutes *int                   `json:"rushCooldownMinutes,omitempty"`
	RushRepliedAt       *time.Time             `json:"rushRepliedAt,omitempty"`
	RushRequestedAt     *time.Time             `json:"rushRequestedAt,omitempty"`
	ScheduledAt         *time.Time             `json:"scheduledAt,omitempty"`
	Seen                *bool                  `json:"seen,omitempty"`
	SettledAt           *time.Time             `json:"settledAt,omitempty"`
	Source              *EnterpriseOrderSource `json:"source,omitempty"`
	Status              OrderStatus            `json:"status"`
	StoreId             *openapi_types.UUID    `json:"storeId,omitempty"`

	// TipTZS Rider tip (打赏) received on this order
	TipTZS    *int           `json:"tipTZS,omitempty"`
	Totals    PriceBreakdown `json:"totals"`
	UpdatedAt *time.Time     `json:"updatedAt,omitempty"`

	// Version Optimistic-concurrency version; mutations send expectedVersion
	Version *int `json:"version,omitempty"`

	// WaitPayTZS Wait-time compensation
	WaitPayTZS *int `json:"waitPayTZS,omitempty"`

	// WaitSeconds Restaurant wait time tracked by the wait timer
	WaitSeconds *int `json:"waitSeconds,omitempty"`

	// WaybillNumber Tracking number across all legs
	WaybillNumber *string `json:"waybillNumber,omitempty"`
}

